pub(crate) fn trim(&mut self, trim_idx: Option<usize>) -> Result<(), CompactionErr> {
    match self.state {
        (Role::Leader, _) => {
            let min_all_accepted_idx = self.leader_state.get_min_all_accepted_idx();
            let trimmed_idx = match trim_idx {
                Some(idx) if idx <= *min_all_accepted_idx => idx,
                None => {
                    #[cfg(feature = "logging")]
                    trace!(
                        self.logger,
                        "No trim index provided, using min_las_idx: {:?}",
                        min_all_accepted_idx
                    );
                    *min_all_accepted_idx
                }
                _ => {
                    return Err(CompactionErr::NotAllDecided(*min_all_accepted_idx));
                }
            };
            let result = self.internal_storage.try_trim(trimmed_idx);
            if result.is_ok() {
                for pid in &self.peers {
                    let msg = PaxosMsg::Compaction(Compaction::Trim(trimmed_idx));
                    self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                        from: self.pid,
                        to: *pid,
                        msg,
                    }));
                }
            }
            result.map_err(|e| {
                *e.downcast()
                    .expect("storage error while trying to trim log")
            })
        }
        _ => Err(CompactionErr::NotCurrentLeader(self.get_current_leader())),
    }
}

pub(crate) fn try_trim(&mut self, idx: usize) -> StorageResult<()> {
    let decided_idx = self.get_decided_idx();
    let log_decided_idx = self.get_decided_idx_without_stopsign();
    let new_compacted_idx = match idx.cmp(&decided_idx) {
        Ordering::Less => idx,
        Ordering::Equal => log_decided_idx,
        Ordering::Greater => Err(CompactionErr::UndecidedIndex(decided_idx))?,
    };
    if new_compacted_idx > self.get_compacted_idx() {
        self.storage.write_atomically(vec![
            StorageOp::Trim(new_compacted_idx),
            StorageOp::SetCompactedIdx(new_compacted_idx),
        ])?;
        self.state_cache.compacted_idx = new_compacted_idx;
    }
    Ok(())
}

pub(crate) fn try_snapshot(&mut self, snapshot_idx: Option<usize>) -> StorageResult<()> {
    let decided_idx = self.get_decided_idx();
    let log_decided_idx = self.get_decided_idx_without_stopsign();
    let new_compacted_idx = match snapshot_idx {
        Some(i) => match i.cmp(&decided_idx) {
            Ordering::Less => i,
            Ordering::Equal => log_decided_idx,
            Ordering::Greater => Err(CompactionErr::UndecidedIndex(decided_idx))?,
        },
        None => log_decided_idx,
    };
    if new_compacted_idx > self.get_compacted_idx() {
        let snapshot = self.create_snapshot(new_compacted_idx)?;
        self.storage.write_atomically(vec![
            StorageOp::Trim(new_compacted_idx),
            StorageOp::SetCompactedIdx(new_compacted_idx),
            StorageOp::SetSnapshot(Some(snapshot)),
        ])?;
        self.state_cache.compacted_idx = new_compacted_idx;
    }
    Ok(())
}

pub(crate) fn snapshot(
    &mut self,
    idx: Option<usize>,
    local_only: bool,
) -> Result<(), CompactionErr> {
    let result = self.internal_storage.try_snapshot(idx);
    if !local_only && result.is_ok() {
        // since it is decided, it is ok even for a follower to send this
        for pid in &self.peers {
            let msg = PaxosMsg::Compaction(Compaction::Snapshot(idx));
            self.outgoing.push(Message::SequencePaxos(PaxosMessage {
                from: self.pid,
                to: *pid,
                msg,
            }));
        }
    }
    result.map_err(|e| {
        *e.downcast()
            .expect("storage error while trying to snapshot log")
    })
}

